#include <map>
#include <algorithm>

std::map<int, int> data = {{1, 10}, {2, 20}, {3, 30}};

// 1. Key Search: O(log N)
auto pos_key = data.find(2);

// 2. Value Search: O(N)
// Predicate checks the mapped value (second element of pair)
auto pos_value = std::find_if(data.begin(), data.end(), 
    [](const std::pair<const int, int>& elem) {
        return elem.second == 30;
    }
);

